'use strict';

const tabs = [...document.querySelectorAll('.tab-button')];
const indicator = document.querySelector('.tab-indicator');
const loginPanel = document.querySelector('#login-panel');
const registerPanel = document.querySelector('#register-panel');
const signedIn = document.querySelector('#signed-in');
const loginCard = document.querySelector('#login-card');
const adminApp = document.querySelector('#admin-app');
const roleApp = document.querySelector('#role-app');
const roleContent = document.querySelector('#role-content');
const adminContent = document.querySelector('#admin-content');
const toast = document.querySelector('#toast');
const drawer = document.querySelector('#detail-drawer');
const drawerBackdrop = document.querySelector('#drawer-backdrop');
const drawerContent = document.querySelector('#drawer-content');
const dialog = document.querySelector('#decision-dialog');
const state = { view:'dashboard', user:null, classes:[], subjects:[], timer:null, dialogRequest:null, dashboard:null, absenceOffset:0, roleLesson:null, roleDate:'', parentTab:'timetable', parentData:null, parentWeekStart:'' };

function showTab(name) {
  const registering = name === 'register';
  tabs.forEach((tab,index) => {
    const active=index===(registering?1:0);tab.classList.toggle('active',active);tab.setAttribute('aria-selected',String(active));
  });
  indicator.style.transform=registering?'translateX(116px)':'translateX(0)';
  indicator.style.width=registering?'129px':'76px';loginPanel.hidden=registering;registerPanel.hidden=!registering;
}
if(tabs[0]&&tabs[1]){tabs[0].addEventListener('click',()=>showTab('login'));tabs[1].addEventListener('click',()=>showTab('register'));}
tabs.forEach((tab,index)=>tab.addEventListener('keydown',event=>{
  if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();const next=tabs[index===0?1:0];next.focus();next.click();}
}));
document.querySelectorAll('[data-toggle-password]').forEach(button=>button.addEventListener('click',()=>{
  const input=document.getElementById(button.dataset.togglePassword),visible=input.type==='password';input.type=visible?'text':'password';button.textContent=visible?'Masquer':'Afficher';button.setAttribute('aria-label',visible?'Masquer le mot de passe':'Afficher le mot de passe');
}));

function message(id,text,success=false){const target=document.getElementById(id);target.textContent=text;target.classList.toggle('success',success);}
async function directionQuery(url,options={}){return window.directionData(url,options);}

function showSession(user){
  const destination={DIRECTION:window.smartSchoolPath('admin/'),TEACHER:window.smartSchoolPath('teacher/'),PARENT:window.smartSchoolPath('parent/')}[user.role];
  if(destination&&!window.location.pathname.startsWith(destination)){window.location.replace(destination);return;}
  if(user.role==='DIRECTION'){
    if(loginCard)loginCard.hidden=true;const footer=document.querySelector('footer');if(footer)footer.hidden=true;if(adminApp)adminApp.hidden=false;state.user=user;
    document.querySelector('#admin-user-name').textContent=user.fullName||'Direction';
    document.querySelector('.profile-avatar').textContent=initials(user.fullName||'D');
    document.querySelector('.top-avatar').textContent=initials(user.fullName||'D');
    startAdmin();return;
  }
  // Parent and teacher pages have their own scripts. Replacing the current
  // location here when it already matches the role route reloads that page
  // repeatedly whenever this shared session check runs.
}
function resetLogin(){adminApp.hidden=true;roleApp.hidden=true;loginCard.hidden=false;document.querySelector('footer').hidden=false;signedIn.hidden=true;document.querySelector('.tab-list').hidden=false;showTab('login');}

function schoolToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Casablanca',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function mondayOf(date){const d=new Date(`${date}T00:00:00Z`);d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10);}
function shiftWeek(date,amount){const d=new Date(`${date}T00:00:00Z`);d.setUTCDate(d.getUTCDate()+amount*7);return d.toISOString().slice(0,10);}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function initials(value){return String(value||'').trim().split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toUpperCase()||'SC';}
function dateLabel(value,options={dateStyle:'medium'}){if(!value)return'—';const date=/^\d{4}-\d{2}-\d{2}$/.test(value)?new Date(`${value}T12:00:00+01:00`):new Date(value);if(Number.isNaN(date.getTime()))return esc(value);return new Intl.DateTimeFormat('fr-MA',{...options,timeZone:'Africa/Casablanca'}).format(date);}
function lessonDurationLabel(start,end){const toMinutes=t=>{const m=/^(\d{2}):(\d{2})$/.exec(String(t||''));return m?Number(m[1])*60+Number(m[2]):null;},a=toMinutes(start),b=toMinutes(end);return a===null||b===null||b<=a?'—':`${new Intl.NumberFormat('fr-MA',{maximumFractionDigits:2}).format((b-a)/60)} h`;}
function statusLabel(status){return({ACTIVE:'Actif',INACTIVE:'Inactif',RESET_REQUIRED:'Changement requis',PENDING:'En attente',REJECTED:'Refusé',APPROUVEE:'Approuvée',EN_ATTENTE:'En attente',REFUSEE:'Refusée',PRESENT:'Présent',ABSENT:'Absent',NOT_RECORDED:'Non saisi',AUTORISEE:'Autorisée',true:'Lu',false:'Non lu'})[status]??(status||'—');}
function badge(status){let cls='neutral';if(['ACTIVE','APPROUVEE','PRESENT','AUTORISEE','true'].includes(status))cls=status==='PRESENT'?'present':'active';if(['PENDING','EN_ATTENTE','RESET_REQUIRED','NOT_RECORDED','false'].includes(status))cls=status==='NOT_RECORDED'?'not-recorded':'pending';if(['REJECTED','REFUSEE','ABSENT'].includes(status))cls=status==='ABSENT'?'absent':'rejected';return`<span class="status-badge ${cls}">${esc(statusLabel(status))}</span>`;}
function heading(title,subtitle,meta=''){return`<div class="page-heading"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${meta?`<span class="heading-meta">${meta}</span>`:''}</div>`;}
function panel(title,body,action=''){return`<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2></div>${action}</div><div class="panel-body">${body}</div></section>`;}
function avatar(name,modifier=''){return`<span class="row-avatar ${modifier}">${esc(initials(name))}</span>`;}
function setLoading(title,subtitle){adminContent.innerHTML=`<div class="content-wrap">${heading(title,subtitle)}<div class="panel loading-state">Chargement des informations…</div></div>`;}
function showPageError(error){adminContent.innerHTML=`<div class="content-wrap">${heading('Une erreur est survenue','La page n’a pas pu être chargée.') }<div class="inline-error">${esc(error.message||'Vérifiez la connexion au serveur local, puis réessayez.')}</div><button class="button-small" style="margin-top:12px" data-retry-view="1">Réessayer</button></div>`;}
function showToast(text,success=true){let target=document.querySelector('.toast-admin');if(!target){target=document.createElement('div');target.className='toast-admin';target.setAttribute('role','status');document.body.append(target);}target.textContent=text;target.classList.add('visible');target.style.background=success?'#1f2d49':'#9f383e';clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>target.classList.remove('visible'),2800);}
function classSelectOptions(selected=''){return`<option value="">Toutes les classes</option>${state.classes.map(c=>`<option value="${esc(c.class_id)}" ${selected===c.class_id?'selected':''}>${esc(c.class_id)}</option>`).join('')}`;}
function setActiveView(view){state.view=view;document.querySelectorAll('.nav-item').forEach(button=>button.classList.toggle('active',button.dataset.view===view));const names={dashboard:'Tableau de bord',students:'Élèves',teachers:'Enseignants',parents:'Parents',classes:'Classes',absences:'Absences',timetable:'Emploi du temps',requests:"Demandes d'inscription",notifications:'Notifications',settings:'Paramètres',accounts:'Comptes'};document.querySelector('#top-page-title').textContent=names[view]||'Tableau de bord';document.querySelector('#admin-app').classList.remove('menu-open');}
async function startAdmin(){
  const currentHash=location.hash.match(/^#\/direction\/([a-z]+)$/)?.[1];
  try{const result=await directionQuery('/direction/classes');state.classes=result.classes||[];}catch{/* The page loader shows API errors. */}
  if(currentHash&&['dashboard','students','teachers','parents','classes','absences','timetable','requests','notifications','settings','accounts'].includes(currentHash))state.view=currentHash;
  loadView(state.view);
}
function loadView(view){setActiveView(view);history.replaceState(null,'',`${window.location.pathname}#/direction/${view}`);const renderers={dashboard:renderDashboard,students:renderStudents,teachers:renderTeachers,parents:renderParents,classes:renderClasses,absences:renderAbsences,timetable:renderTimetable,requests:renderRequests,notifications:renderNotifications,settings:renderSettings,accounts:renderAccounts};(renderers[view]||renderDashboard)();}

async function renderDashboard(){
  setLoading('Tableau de bord','Résumé de la vie scolaire et des actions à suivre.');
  try{
    const data=await directionQuery('/direction/dashboard');state.dashboard=data;
    document.querySelector('#today-chip').textContent=data.todayLabel||'';
    document.querySelector('#student-count').textContent=data.totals.students;
    document.querySelector('#request-count').textContent=data.pendingRequestCount||'';
    const attendance=data.attendance,known=attendance.PRESENT+attendance.ABSENT;
    const attendancePanel=`<div class="attendance-summary"><div class="attendance-stat present"><span>Présents</span><strong>${attendance.PRESENT}</strong></div><div class="attendance-stat absent"><span>Absents</span><strong>${attendance.ABSENT}</strong></div><div class="attendance-stat unrecorded"><span>Non saisis</span><strong>${attendance.NOT_RECORDED}</strong></div></div>${known+attendance.NOT_RECORDED?`<div class="attendance-empty"><span class="attendance-empty-icon">◷</span><span>${known+attendance.NOT_RECORDED} appel(s) enregistré(s) pour aujourd’hui.</span></div>`:`<div class="attendance-empty"><span class="attendance-empty-icon">◷</span><span>Aucun appel n’est enregistré pour aujourd’hui.</span></div>`}`;
    const absences=data.recentAbsences.length?`<div class="compact-list">${data.recentAbsences.map(row=>`<div class="compact-row"><span class="row-avatar" style="background:#fff0ef;color:#bd4d51">${esc(initials(row.student_name))}</span><div class="row-copy"><strong>${esc(row.student_name)}</strong><span>${esc(row.class_id)} · ${esc(row.subject_name)} · ${esc(row.slot_code)}</span></div><div class="row-side">${dateLabel(row.lesson_date)}<br>${badge('ABSENT')}</div></div>`).join('')}</div>`:`<div class="empty-state"><strong>Aucune absence enregistrée</strong>Les absences apparaîtront ici après la saisie des appels.</div>`;
    const requests=data.pendingRequests.length?`<div class="compact-list">${data.pendingRequests.map(request=>`<div class="request-row"><div class="request-main">${avatar(request.parent_name)}<div class="row-copy"><strong>${esc(request.parent_name)}</strong><span>${esc(request.child_name)} · ${esc(request.class_id)} n° ${esc(request.class_number)}</span><span>${esc(request.massar_id)} · reçue le ${dateLabel(request.submitted_at)}</span></div></div><div class="request-actions"><button class="button-small" data-request-action="approve" data-request-id="${esc(request.request_id)}">Approuver</button><button class="button-small danger" data-request-action="reject" data-request-id="${esc(request.request_id)}" data-child="${esc(request.child_name)}">Refuser</button></div></div>`).join('')}</div>`:`<div class="empty-state"><strong>Aucune demande en attente</strong>Les nouvelles demandes seront affichées ici.</div>`;
    const activities=data.activity.length?`<div>${data.activity.map(item=>`<div class="activity-item"><span class="activity-dot"></span><div class="activity-copy">${esc(activityLabel(item.action))}<span>${esc(item.actor_name)} · ${dateLabel(item.created_at,{dateStyle:'medium',timeStyle:'short'})}</span></div></div>`).join('')}</div>`:`<div class="empty-state"><strong>Aucune activité récente</strong>Les actions de gestion apparaîtront ici.</div>`;
    adminContent.innerHTML=`<div class="content-wrap"><div class="greeting"><div class="page-heading"><div><h1>Bonjour, ${esc(state.user?.fullName||'Direction')}</h1><p>Voici le résumé de votre établissement.</p></div><span class="heading-meta">${esc(data.todayLabel||'')}</span></div><div class="greeting-sub">Année scolaire 2026–2027 · Données actualisées depuis les dossiers locaux</div></div><div class="metric-grid">${metric('Élèves',data.totals.students,'♙','',"Vue d’ensemble de l’effectif")}${metric('Enseignants',data.totals.teachers,'♧','green','Équipe pédagogique')}${metric('Parents',data.totals.parents,'♡','purple','Fiches parent enregistrées')}${metric('Classes',data.totals.classes,'▦','orange','Groupes de l’établissement')}</div><div class="dashboard-grid"><div class="dashboard-stack">${panel('Présences aujourd’hui',attendancePanel,`<button class="text-link" data-open-view="absences">Voir les appels</button>`)}${panel('Absences récentes',absences,`<button class="text-link" data-open-view="absences">Toutes les absences</button>`)}</div><div class="dashboard-stack">${panel(`Demandes en attente (${data.pendingRequestCount})`,requests,`<button class="text-link" data-open-view="requests">Ouvrir les demandes</button>`)}${panel('Activité récente',activities,`<button class="text-link" data-open-view="notifications">Notifications</button>`)}</div></div><div class="data-notice"><span>i</span><p>Les renseignements initiaux sur les personnes et les historiques sont générés et doivent être vérifiés avant toute utilisation officielle.</p></div></div>`;
  }catch(error){showPageError(error);}
}
function metric(label,value,icon,color,foot){return`<article class="metric-card"><div class="metric-top"><span>${esc(label)}</span><span class="metric-icon ${color}">${icon}</span></div><div class="metric-value">${esc(value)}</div><div class="metric-foot">${esc(foot)}</div></article>`;}
function activityLabel(action){return({LOGIN:'Connexion à l’espace Direction',LOGOUT:'Déconnexion',PARENT_REGISTRATION_SUBMITTED:'Nouvelle demande d’inscription parent',PARENT_REQUEST_APPROUVEE:'Demande parent approuvée',PARENT_REQUEST_REFUSEE:'Demande parent refusée',NOTIFICATION_READ:'Notification consultée',SCHOOL_SETTINGS_UPDATED:'Paramètres de l’établissement modifiés'})[action]||String(action||'Action enregistrée').replaceAll('_',' ').toLocaleLowerCase('fr');}

function renderStudents(){
  adminContent.innerHTML=`<div class="content-wrap">${heading('Élèves','Recherchez une fiche par nom, Code Massar, classe ou numéro de classe.',`<button class="button-small" data-new-student>+ Nouvel élève</button>`) }<div class="toolbar"><label class="search-box"><input id="student-search" type="search" placeholder="Nom, Code Massar, classe ou numéro" autocomplete="off"></label><select class="filter-select" id="student-class">${classSelectOptions()}</select><input class="filter-input" id="student-number" type="number" min="1" max="60" placeholder="N° dans la classe"><span class="result-count" id="student-results"></span></div><section class="panel"><div class="data-table-wrap" id="table-region"><div class="loading-state">Chargement des élèves…</div></div></section></div>`;
  const refresh=()=>loadStudentRows();document.querySelector('#student-search').addEventListener('input',debounce(refresh));document.querySelector('#student-class').addEventListener('change',refresh);document.querySelector('#student-number').addEventListener('input',debounce(refresh));loadStudentRows();
}
function debounce(callback){return()=>{clearTimeout(state.timer);state.timer=setTimeout(callback,220);};}
async function loadStudentRows(){if(state.view!=='students')return;try{const params=new URLSearchParams();const q=document.querySelector('#student-search')?.value||'',classId=document.querySelector('#student-class')?.value||'',number=document.querySelector('#student-number')?.value||'';if(q)params.set('q',q);if(classId)params.set('class_id',classId);if(number)params.set('class_number',number);const data=await directionQuery(`/direction/students?${params}`);const region=document.querySelector('#table-region');if(!region)return;document.querySelector('#student-results').textContent=`${data.students.length} fiche(s)`;region.innerHTML=data.students.length?`<table class="data-table"><thead><tr><th>Élève</th><th>Code Massar</th><th>Classe</th><th>Numéro</th><th>Parent lié</th><th>Téléphone</th><th>Statut</th></tr></thead><tbody>${data.students.map(s=>`<tr class="click-row" data-detail="student" data-id="${esc(s.student_id)}"><td><div class="table-person">${avatar(s.full_name)}<strong>${esc(s.full_name)}</strong></div></td><td>${esc(s.massar_id)}</td><td>${esc(s.class_id)}</td><td>${esc(s.class_number)}</td><td>${esc(s.parent_name||'—')}</td><td>${esc(s.parent_phone||'—')}</td><td>${badge(s.status==='Actif'?'ACTIVE':'neutral')}</td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><strong>Aucun élève trouvé</strong>Essayez un autre nom, Code Massar ou filtre.</div>`;}catch(error){tableError(error);}}
function tableError(error){const region=document.querySelector('#table-region');if(region)region.innerHTML=`<div class="inline-error">${esc(error.message)}</div>`;}

function renderTeachers(){
  adminContent.innerHTML=`<div class="content-wrap">${heading('Enseignants','Consultez les profils, matières, classes et horaires de l’équipe.',`<button class="button-small" data-new-teacher>+ Nouvel enseignant</button>`) }<div class="toolbar"><label class="search-box"><input id="teacher-search" type="search" placeholder="Rechercher un enseignant ou une matière" autocomplete="off"></label><select class="filter-select" id="teacher-subject"><option value="">Toutes les matières</option>${state.subjects.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}</select><select class="filter-select" id="teacher-shift"><option value="">Tous les shifts</option><option>Matin</option><option>Après-midi</option></select><span class="result-count" id="teacher-results"></span></div><section class="panel"><div class="data-table-wrap" id="table-region"><div class="loading-state">Chargement des enseignants…</div></div></section></div>`;
  const refresh=()=>loadTeacherRows();document.querySelector('#teacher-search').addEventListener('input',debounce(refresh));document.querySelector('#teacher-subject').addEventListener('change',refresh);document.querySelector('#teacher-shift').addEventListener('change',refresh);loadTeacherRows();
}
async function loadTeacherRows(){if(state.view!=='teachers')return;try{const params=new URLSearchParams();const q=document.querySelector('#teacher-search')?.value||'',subject=document.querySelector('#teacher-subject')?.value||'',shift=document.querySelector('#teacher-shift')?.value||'';if(q)params.set('q',q);if(subject)params.set('subject',subject);if(shift)params.set('shift',shift);const data=await directionQuery(`/direction/teachers?${params}`);state.subjects=data.subjects;const region=document.querySelector('#table-region');if(!region)return;const sub=document.querySelector('#teacher-subject'),selected=sub.value;if(sub.options.length===1)sub.innerHTML=`<option value="">Toutes les matières</option>${state.subjects.map(s=>`<option value="${esc(s)}">${esc(s)}</option>`).join('')}`;sub.value=selected;document.querySelector('#teacher-results').textContent=`${data.teachers.length} enseignant(s)`;region.innerHTML=data.teachers.length?`<table class="data-table"><thead><tr><th>Enseignant</th><th>Matière</th><th>Équipe</th><th>Classes assignées</th><th>Heures / semaine</th><th>Statut</th></tr></thead><tbody>${data.teachers.map(t=>`<tr class="click-row" data-detail="teacher" data-id="${esc(t.teacher_id)}"><td><div class="table-person">${avatar(t.full_name)}<strong>${esc(t.full_name)}<span>${esc(t.teacher_id)}</span></strong></div></td><td>${esc(t.subject_name)}</td><td>${esc(t.shift)}</td><td>${esc((t.classes||'').split(',').filter(Boolean).join(', ')||'—')}</td><td>${esc(t.weekly_hours)}</td><td>${badge(t.status==='Actif'?'ACTIVE':'neutral')}</td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><strong>Aucun enseignant trouvé</strong>Essayez un autre nom ou une matière.</div>`;}catch(error){tableError(error);}}

function renderParents(){adminContent.innerHTML=`<div class="content-wrap">${heading('Parents','Chaque fiche est liée à un seul élève. Les comptes en attente ne peuvent pas se connecter.') }<div class="toolbar"><label class="search-box"><input id="parent-search" type="search" placeholder="Nom, élève, Massar, classe, courriel ou téléphone" autocomplete="off"></label><select class="filter-select" id="parent-status"><option value="">Tous les statuts</option><option value="ACTIVE">Compte actif</option><option value="PENDING">En attente</option><option value="REJECTED">Refusé</option></select><span class="result-count" id="parent-results"></span></div><section class="panel"><div class="data-table-wrap" id="table-region"><div class="loading-state">Chargement des parents…</div></div></section></div>`;const refresh=()=>loadParentRows();document.querySelector('#parent-search').addEventListener('input',debounce(refresh));document.querySelector('#parent-status').addEventListener('change',refresh);loadParentRows();}
async function loadParentRows(){if(state.view!=='parents')return;try{const params=new URLSearchParams(),q=document.querySelector('#parent-search')?.value||'',status=document.querySelector('#parent-status')?.value||'';if(q)params.set('q',q);if(status)params.set('status',status);const data=await directionQuery(`/direction/parents?${params}`);const region=document.querySelector('#table-region');if(!region)return;document.querySelector('#parent-results').textContent=`${data.parents.length} parent(s)`;region.innerHTML=data.parents.length?`<table class="data-table"><thead><tr><th>Parent</th><th>Élève lié</th><th>Code Massar</th><th>Classe</th><th>Courriel</th><th>Téléphone</th><th>Compte</th><th>Inscription</th></tr></thead><tbody>${data.parents.map(p=>`<tr><td><div class="table-person">${avatar(p.full_name)}<strong>${esc(p.full_name)}</strong></div></td><td>${esc(p.child_name)}</td><td>${esc(p.child_massar_id)}</td><td>${esc(p.class_id)} · ${esc(p.class_number)}</td><td>${esc(p.email||'—')}</td><td>${esc(p.phone||'—')}</td><td>${badge(p.account_status)}</td><td>${badge(p.registration_status)}</td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><strong>Aucun parent trouvé</strong>Essayez un autre terme de recherche.</div>`;}catch(error){tableError(error);}}

async function renderClasses(){adminContent.innerHTML=`<div class="content-wrap">${heading('Classes','Effectifs, rythmes hebdomadaires et emplois du temps.',`<button class="button-small" data-new-class>+ Nouvelle classe</button>`) }<div class="class-grid" id="class-grid"><div class="panel loading-state">Chargement des classes…</div></div></div>`;try{const data=await directionQuery('/direction/classes');adminContent.querySelector('#class-grid').innerHTML=data.classes.map(c=>`<article class="class-card" role="button" tabindex="0" data-detail="class" data-id="${esc(c.class_id)}"><div class="class-card-top"><strong class="class-code">${esc(c.class_id)}</strong><span class="class-symbol">▦</span></div><div class="class-stats"><div class="class-stat"><strong>${esc(c.student_count)}</strong><span>élèves</span></div><div class="class-stat"><strong>${esc(c.lesson_count)}</strong><span>cours / semaine</span></div><div class="class-stat"><strong>${esc(c.track||'—')}</strong><span>filière</span></div></div><div class="class-card-foot"><span>${esc(c.level||'')}</span><span>Voir la classe →</span></div></article>`).join('');}catch(error){showPageError(error);}}

function renderAbsences(){state.absenceOffset=0;adminContent.innerHTML=`<div class="content-wrap">${heading('Absences et présences','Historique par élève, classe, Code Massar, cours et date. Les états restent distincts.') }<div class="toolbar"><label class="search-box"><input id="absence-search" type="search" placeholder="Élève, Massar, classe, numéro, cours" autocomplete="off"></label><select class="filter-select" id="absence-class">${classSelectOptions()}</select><select class="filter-select" id="absence-status"><option value="">Tous les états</option><option value="PRESENT">Présent</option><option value="ABSENT">Absent</option><option value="NOT_RECORDED">Non saisi</option></select><input class="filter-input" id="absence-from" type="date" aria-label="Date de début"><input class="filter-input" id="absence-to" type="date" aria-label="Date de fin"><input class="filter-input" id="absence-lesson" type="search" placeholder="Identifiant du cours" aria-label="Identifiant du cours"><span class="result-count" id="absence-results"></span></div><section class="panel workflow-panel"><div class="panel-head"><div><h2>Justifications et retours</h2><p>Décisions et autorisations en attente</p></div></div><div class="panel-body" id="attendance-workflows"><div class="loading-state">Chargement des décisions…</div></div></section><section class="panel"><div class="data-table-wrap" id="table-region"><div class="loading-state">Chargement des présences…</div></div><div id="absence-pagination"></div></section></div>`;const refresh=()=>{state.absenceOffset=0;loadAbsenceRows();};document.querySelector('#absence-search').addEventListener('input',debounce(refresh));for(const id of ['absence-class','absence-status','absence-from','absence-to','absence-lesson'])document.querySelector(`#${id}`).addEventListener('change',refresh);loadAbsenceRows();loadAttendanceWorkflows();}
async function loadAbsenceRows(){if(state.view!=='absences')return;try{const params=new URLSearchParams();const values={q:document.querySelector('#absence-search')?.value,class_id:document.querySelector('#absence-class')?.value,status:document.querySelector('#absence-status')?.value,date_from:document.querySelector('#absence-from')?.value,date_to:document.querySelector('#absence-to')?.value,lesson_id:document.querySelector('#absence-lesson')?.value,limit:100,offset:state.absenceOffset};for(const[k,v]of Object.entries(values))if(v!==''&&v!=null)params.set(k,v);const data=await directionQuery(`/direction/absences?${params}`);const region=document.querySelector('#table-region');if(!region)return;document.querySelector('#absence-results').textContent=`${data.total} résultat(s)`;region.innerHTML=data.records.length?`<table class="data-table"><thead><tr><th>Date</th><th>Élève</th><th>Code Massar</th><th>Classe</th><th>N°</th><th>Matière / cours</th><th>Enseignant</th><th>Horaire</th><th>Présence</th><th>Justification</th><th>Correction</th></tr></thead><tbody>${data.records.map(r=>`<tr><td>${dateLabel(r.lesson_date)}</td><td><button class="table-link" data-detail="student" data-id="${esc(r.student_id)}">${esc(r.student_name)}</button></td><td>${esc(r.massar_id)}</td><td>${esc(r.class_id)}</td><td>${esc(r.class_number)}</td><td>${esc(r.subject_name)}<br><span class="decision-note">${esc(r.lesson_code)}</span></td><td>${esc(r.teacher_name)}</td><td>${esc(r.slot_code)}</td><td>${badge(r.status)}${r.corrected_status?`<br><span class="decision-note">Corrigé : ${esc(statusLabel(r.corrected_status))}</span>`:''}</td><td>${r.explanation_status?badge(r.explanation_status):'—'}</td><td><button class="button-small" data-correct-attendance="${esc(r.attendance_id)}" data-student="${esc(r.student_name)}" data-lesson="${esc(r.subject_name)}" data-date="${esc(r.lesson_date)}" data-slot="${esc(r.slot_code)}" data-current="${esc(r.corrected_status||r.status)}">Corriger</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><strong>Aucun enregistrement pour ces filtres</strong>Les lignes Non saisi ne sont pas comptées comme des absences.</div>`;const first=data.total?data.offset+1:0,last=data.offset+data.records.length;document.querySelector('#absence-pagination').innerHTML=data.total>100?`<div class="pagination-bar"><span>Affichage ${first}–${last} sur ${data.total}</span><div><button class="button-small" data-absence-page="previous" ${data.offset===0?'disabled':''}>Précédent</button><button class="button-small" data-absence-page="next" ${data.offset+data.records.length>=data.total?'disabled':''}>Suivant</button></div></div>`:'';}catch(error){tableError(error);}}
async function loadAttendanceWorkflows(){const region=document.querySelector('#attendance-workflows');if(!region)return;try{const [explanationData,returnData]=await Promise.all([directionQuery('/direction/absence-explanations?status=EN_ATTENTE'),directionQuery('/direction/entry-decisions')]);const explanations=explanationData.explanations.filter(e=>e.status==='EN_ATTENTE'),returns=returnData.decisions.filter(d=>d.hold_status==='ACTIVE');const cards=[...explanations.map(e=>`<article class="workflow-row"><div><strong>${esc(e.student_name)} · ${dateLabel(e.absence_date)} · ${esc(e.subject_name)}</strong><span>${esc(e.reason)}</span>${explanationData.documents.filter(d=>d.explanation_id===e.explanation_id).map(d=>`<a class="document-link" href="${esc(d.download_url)}" target="_blank" rel="noopener">Consulter : ${esc(d.original_filename)}</a>`).join('')}</div><div class="workflow-actions"><button class="button-small" data-explanation-decision="APPROUVEE" data-explanation-id="${esc(e.explanation_id)}">Approuver</button><button class="button-small danger" data-explanation-decision="REFUSEE" data-explanation-id="${esc(e.explanation_id)}">Refuser</button></div></article>`),...returns.map(d=>{const options=returnData.lessons.filter(l=>l.class_id===d.class_id).map(l=>`<option value="${esc(l.lesson_id)}">${esc(l.day)} · ${esc(l.slot_code)} · ${esc(l.subject_name)}</option>`).join('');return`<article class="workflow-row return-row"><div><strong>${esc(d.student_name)} · absence du ${dateLabel(d.absence_date)}</strong><span>${esc(d.subject_name)} · Décision actuelle : ${badge(d.status)}${d.authorized_lesson_id?` · ${esc(d.authorized_lesson_id)} le ${dateLabel(d.authorized_lesson_date)}`:''}</span></div><div class="return-form"><select data-return-lesson="${esc(d.decision_id)}"><option value="">Cours de retour</option>${options}</select><input type="date" data-return-date="${esc(d.decision_id)}" min="${esc(schoolToday())}"><input type="text" maxlength="500" placeholder="Motif / consigne" data-return-reason="${esc(d.decision_id)}"><button class="button-small" data-entry-decision="AUTORISEE" data-entry-id="${esc(d.decision_id)}">Autoriser</button><button class="button-small danger" data-entry-decision="REFUSEE" data-entry-id="${esc(d.decision_id)}">Refuser</button></div></article>`;})];region.innerHTML=cards.length?cards.join(''):`<div class="empty-state"><strong>Aucune décision en attente</strong>Les nouvelles justifications et demandes de retour apparaîtront ici.</div>`;}catch(error){region.innerHTML=`<div class="inline-error">${esc(error.message)}</div>`;}}

async function renderTimetable(){adminContent.innerHTML=`<div class="content-wrap">${heading('Emploi du temps','Vue hebdomadaire des 120 cours fournis. Le tableau présente les horaires enregistrés.') }<div class="toolbar"><select class="filter-select" id="timetable-class">${classSelectOptions()}</select><select class="filter-select" id="timetable-teacher"><option value="">Tous les enseignants</option></select><select class="filter-select" id="timetable-day"><option value="">Toute la semaine</option>${['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'].map(d=>`<option>${d}</option>`).join('')}</select><span class="result-count" id="timetable-results"></span></div><section class="panel"><div class="schedule-scroll" id="table-region"><div class="loading-state">Chargement de l’emploi du temps…</div></div></section></div>`;document.querySelector('#timetable-class').addEventListener('change',loadTimetableRows);document.querySelector('#timetable-teacher').addEventListener('change',loadTimetableRows);document.querySelector('#timetable-day').addEventListener('change',loadTimetableRows);loadTimetableRows();}
async function loadTimetableRows(){if(state.view!=='timetable')return;try{const params=new URLSearchParams(),classId=document.querySelector('#timetable-class')?.value||'',teacherId=document.querySelector('#timetable-teacher')?.value||'',day=document.querySelector('#timetable-day')?.value||'';if(classId)params.set('class_id',classId);if(teacherId)params.set('teacher_id',teacherId);if(day)params.set('day',day);const data=await directionQuery(`/direction/timetable?${params}`);const teacherSelect=document.querySelector('#timetable-teacher');if(teacherSelect&&teacherSelect.options.length===1){teacherSelect.innerHTML=`<option value="">Tous les enseignants</option>${data.teachers.map(t=>`<option value="${esc(t.teacher_id)}">${esc(t.full_name)}</option>`).join('')}`;}const region=document.querySelector('#table-region');if(!region)return;document.querySelector('#timetable-results').textContent=`${data.lessons.length} cours`;const days=day?[day]:['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'],slots=[['M1','08:00–09:00'],['M2','09:00–10:00'],['M3','10:00–11:00'],['M4','11:00–12:00'],['PAUSE','12:00–14:00'],['S1','14:00–15:00'],['S2','15:00–16:00'],['S3','16:00–17:00'],['S4','17:00–18:00']];let html=`<div class="schedule-grid" style="grid-template-columns:62px repeat(${days.length},minmax(125px,1fr))"><div class="schedule-cell schedule-head">Heure</div>${days.map(d=>`<div class="schedule-cell schedule-head">${esc(d)}</div>`).join('')}`;for(const[code,time]of slots){if(code==='PAUSE'){html+=`<div class="schedule-cell schedule-time">${time}</div><div class="schedule-cell schedule-break" style="grid-column:span ${days.length}">PAUSE · 12:00–14:00</div>`;continue;}html+=`<div class="schedule-cell schedule-time">${code}<br>${time}</div>`;for(const d of days){const lesson=data.lessons.find(l=>l.day===d&&l.slot_code===code);html+=`<div class="schedule-cell">${d==='Dimanche'?'<span class="no-lesson">Fermé</span>':lesson?`<div class="lesson-card" style="--lesson-color:${safeColor(lesson.color)}"><strong>${esc(lesson.subject_name)}</strong><span>${esc(lesson.class_id)} · ${esc(lesson.teacher_name)}<br>${esc(lesson.room)} · ${esc(lesson.start_time)}–${esc(lesson.end_time)}</span><button class="button-small" type="button" data-edit-timetable="${esc(lesson.lesson_id)}">Modifier</button></div>`:(['Vendredi','Samedi'].includes(d)&&code.startsWith('S')?`<span class="no-lesson">Pas de cours</span>`:'')}</div>`;}}html+='</div>';region.innerHTML=html;}catch(error){tableError(error);}}
function safeColor(color){return/^#[0-9a-fA-F]{6}$/.test(color||'')?color:'#5274dd';}

async function renderRequests(){adminContent.innerHTML=`<div class="content-wrap">${heading("Demandes d'inscription",'Examinez les demandes en attente. Une approbation active le compte parent; un refus exige un motif.') }<div class="toolbar"><select class="filter-select" id="request-filter"><option value="">Toutes les demandes</option><option value="EN_ATTENTE">En attente</option><option value="APPROUVEE">Approuvées</option><option value="REFUSEE">Refusées</option></select><span class="result-count" id="request-results"></span></div><section class="panel"><div class="data-table-wrap" id="table-region"><div class="loading-state">Chargement des demandes…</div></div></section></div>`;document.querySelector('#request-filter').addEventListener('change',loadRequestRows);await loadRequestRows();}
async function loadRequestRows(){try{const data=await directionQuery('/direction/parent-requests');const filter=document.querySelector('#request-filter')?.value||'',rows=data.requests.filter(r=>!filter||r.status===filter),region=document.querySelector('#table-region');if(!region)return;document.querySelector('#request-results').textContent=`${rows.length} demande(s)`;region.innerHTML=rows.length?`<table class="data-table"><thead><tr><th>Parent</th><th>Élève demandé / dossier scolaire</th><th>Classe / N°</th><th>Code Massar</th><th>Courriel</th><th>Téléphone</th><th>Soumise le</th><th>Statut</th><th>Décision</th></tr></thead><tbody>${rows.map(r=>{const linked=r.student&&r.student.full_name.trim().toLocaleLowerCase('fr')===String(r.child_name||'').trim().toLocaleLowerCase('fr');return `<tr><td>${esc(r.parent_name)}</td><td>${esc(r.child_name)}<span class="decision-note">${linked?`Dossier trouvé : ${esc(r.student.full_name)} · ${esc(r.student.student_id)}`:'Aucun dossier concordant'}</span></td><td>${esc(r.class_id)} · ${esc(r.class_number)}</td><td>${esc(r.massar_id)}</td><td>${esc(r.email||'—')}</td><td>${esc(r.phone||'—')}</td><td>${dateLabel(r.submitted_at,{dateStyle:'medium',timeStyle:'short'})}</td><td>${badge(r.status)}</td><td>${r.status==='EN_ATTENTE'?`<div class="table-actions"><button class="button-small" data-request-action="approve" data-request-id="${esc(r.request_id)}" ${linked?'':'disabled'}>Approuver</button><button class="button-small danger" data-request-action="reject" data-request-id="${esc(r.request_id)}" data-child="${esc(r.child_name)}">Refuser</button></div>`:`<span class="decision-note">${esc(r.decision_by||'Direction')} · ${dateLabel(r.decision_at)}</span>${r.rejection_reason?`<span class="decision-note">${esc(r.rejection_reason)}</span>`:''}`}</td></tr>`;}).join('')}</tbody></table>`:`<div class="empty-state"><strong>Aucune demande dans cette catégorie</strong>Les demandes d’inscription apparaîtront ici.</div>`;const pending=data.requests.filter(x=>x.status==='EN_ATTENTE').length;document.querySelector('#request-count').textContent=pending||'';}catch(error){tableError(error);}}

async function renderNotifications(){adminContent.innerHTML=`<div class="content-wrap">${heading('Notifications','Messages et événements liés à la gestion de l’établissement.') }<section class="panel"><div class="compact-list panel-body" id="notification-list"><div class="loading-state">Chargement des notifications…</div></div></section></div>`;try{const data=await directionQuery('/direction/notifications');const list=document.querySelector('#notification-list');if(!list)return;const unread=data.notifications.filter(n=>n.is_read!=='true').length;document.querySelector('#notification-dot').style.display=unread?'block':'none';list.innerHTML=data.notifications.length?data.notifications.map(n=>`<div class="compact-row"><span class="row-avatar" style="background:${n.is_read==='true'?'#f0f2f6':'#edf2ff'};color:${n.is_read==='true'?'#8590a4':'#315bd6'}">${n.is_read==='true'?'✓':'!'}</span><div class="row-copy"><strong>${esc(n.title)}</strong><span>${esc(n.message)}</span><span>${dateLabel(n.created_at,{dateStyle:'medium',timeStyle:'short'})}</span></div>${n.is_read==='true'?badge('true'):`<button class="button-small" data-notification-read="${esc(n.notification_id)}">Marquer comme lue</button>`}</div>`).join(''):`<div class="empty-state"><strong>Aucune notification</strong>Il n’y a pas encore de message pour la Direction.</div>`;}catch(error){showPageError(error);}}

async function renderAccounts(){adminContent.innerHTML=`<div class="content-wrap">${heading('Comptes','Gérez les accès parent et enseignant. Les comptes créés ou réinitialisés doivent choisir un nouveau mot de passe.') }<section class="role-card"><h2>Créer un accès enseignant</h2><form id="teacher-account-form" class="simple-form"><label>Fiche enseignant sans compte<select name="teacher_id" required></select></label><button class="button-small" type="submit">Créer le compte enseignant</button><span class="form-feedback" id="account-feedback"></span></form><p class="decision-note">Un mot de passe temporaire sera affiché une seule fois. Remettez-le à l’enseignant par un canal privé.</p></section><section class="panel"><div class="data-table-wrap" id="accounts-region"><div class="loading-state">Chargement des comptes…</div></div></section></div>`;try{const data=await directionQuery('/direction/accounts'),region=document.querySelector('#accounts-region'),select=document.querySelector('#teacher-account-form select');select.innerHTML=data.unlinkedTeachers.length?data.unlinkedTeachers.map(t=>`<option value="${esc(t.teacher_id)}">${esc(t.full_name)} · ${esc(t.login_id)}</option>`).join(''):'<option value="">Aucun enseignant sans compte</option>';document.querySelector('#teacher-account-form button').disabled=!data.unlinkedTeachers.length;region.innerHTML=data.accounts.length?`<table class="data-table"><thead><tr><th>Identifiant</th><th>Nom</th><th>Rôle</th><th>État</th><th>Actions</th></tr></thead><tbody>${data.accounts.map(a=>`<tr><td>${esc(a.account_code)}</td><td>${esc(a.full_name)}</td><td>${esc(a.role)}</td><td>${badge(a.status)}</td><td>${a.status==='ACTIVE'?`<button class="button-small" data-account-status="INACTIVE" data-account-id="${esc(a.id)}" ${a.id===state.user?.id?'disabled':''}>Suspendre</button>${['PARENT','TEACHER'].includes(a.role)?` <button class="button-small danger" data-reset-account="${esc(a.id)}" data-reset-login="${esc(a.account_code)}">Réinitialiser</button>`:''}`:a.status==='INACTIVE'?`<button class="button-small" data-account-status="ACTIVE" data-account-id="${esc(a.id)}">Réactiver</button>`:'<span class="decision-note">Changement obligatoire</span>'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">Aucun compte.</div>';document.querySelector('#teacher-account-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),feedback=document.querySelector('#account-feedback');button.disabled=true;feedback.textContent='';try{const {data:result,error}=await window.smartSchoolSupabase.functions.invoke('direction-account-management',{body:{action:'create_teacher_account',teacher_id:form.elements.teacher_id.value}});if(error||!result?.temporary_password)throw error||new Error('Réponse de création invalide.');showTemporaryCredentials(result.account_id,result.temporary_password,'Compte enseignant créé');showToast('Compte créé. Remettez les informations affichées à l’enseignant.');await renderAccounts();}catch(error){feedback.textContent=error.message||'Le compte n’a pas pu être créé.';}finally{button.disabled=!data.unlinkedTeachers.length;}});}catch(error){showPageError(error);}}
function showTemporaryCredentials(loginId,password,title){openDrawer(`<div class="drawer-heading"><h2>${esc(title)}</h2><p>Ces informations sont affichées une seule fois. Remettez-les directement au titulaire.</p></div><div class="drawer-section"><label>Identifiant<input readonly value="${esc(loginId)}"></label><label>Mot de passe temporaire<input readonly type="text" autocomplete="off" value="${esc(password)}"></label><p class="decision-note">À la première connexion, le titulaire doit créer son propre mot de passe.</p><button class="button-small" type="button" data-copy-temporary>Copier les informations</button><button class="button-small" type="button" data-close-drawer>Fermer</button></div>`);}
async function renderSettings(){adminContent.innerHTML=`<div class="content-wrap">${heading('Paramètres','Informations locales de l’établissement et ressources du jeu initial.') }<section class="panel"><div class="panel-head"><h2>Informations de l’établissement</h2></div><form class="simple-form" id="settings-form"><label>Nom de l’établissement<input name="school_name" required maxlength="120"><small>Ce nom apparaît dans l’en-tête et les documents de l’école.</small></label><label>Année scolaire<input name="school_year" required maxlength="20"><small>Elle sert à présenter les absences de l’année.</small></label><button type="submit">Enregistrer</button><span class="form-feedback" id="settings-feedback"></span></form><button type="button" class="button-small" id="settings-logout">Se déconnecter</button></section><div class="settings-lists"><section class="panel"><div class="panel-head"><h2>Salles disponibles</h2></div><div class="panel-body" id="rooms-list"><div class="loading-state">Chargement…</div></div></section><section class="panel"><div class="panel-head"><h2>Matières</h2><button class="button-small" data-new-subject>+ Ajouter</button></div><div class="panel-body" id="subjects-list"><div class="loading-state">Chargement…</div></div></section></div></div>`;try{const data=await directionQuery('/direction/settings'),form=document.querySelector('#settings-form');form.elements.school_name.value=data.settings.school_name||'';form.elements.school_year.value=data.settings.school_year||'';document.querySelector('#rooms-list').innerHTML=data.rooms.map(r=>`<span class="setting-chip">${esc(r.room_name)}</span>`).join('');document.querySelector('#subjects-list').innerHTML=data.subjects.map(s=>`<div class="setting-subject"><span class="subject-swatch" style="background:${safeColor(s.color)}"></span><span>${esc(s.name)}</span><strong>${esc(s.weekly_hours)} h / classe</strong><button class="button-small" data-edit-subject="${esc(s.code)}">Modifier</button></div>`).join('');form.addEventListener('submit',saveSettings);document.querySelector('#settings-logout').addEventListener('click',async()=>{try{await window.smartSchoolSupabase.auth.signOut({scope:'local'});location.replace(window.smartSchoolPath());}catch(error){showToast('La déconnexion n’a pas pu être confirmée.',false);}});}catch(error){showPageError(error);}}
async function saveSettings(event){event.preventDefault();const form=event.currentTarget,feedback=document.querySelector('#settings-feedback');feedback.textContent='';try{await directionQuery('/direction/settings',{method:'PUT',body:JSON.stringify({school_name:form.elements.school_name.value,school_year:form.elements.school_year.value})});feedback.textContent='Paramètres enregistrés.';feedback.classList.add('success');showToast('Les paramètres ont été enregistrés.');}catch(error){feedback.textContent=error.message;feedback.classList.remove('success');}}

function classForm(c={}){return `<section class="drawer-section"><h3>${c.class_id?'Modifier la classe':'Créer une classe'}</h3><form id="class-form" data-record-id="${esc(c.class_id||'')}"><label>Code de classe<input name="class_id" required maxlength="20" ${c.class_id?'readonly':''} value="${esc(c.class_id||'')}"></label><label>Nom<input name="name" required maxlength="100" value="${esc(c.name||'')}"></label><label>Niveau<input name="level" maxlength="50" value="${esc(c.level||'')}"></label><label>Filière<input name="track" maxlength="50" value="${esc(c.track||'')}"></label><label>Langue<input name="language" maxlength="40" value="${esc(c.language||'')}"></label><label>Effectif prévu<input name="enrollment" type="number" min="0" max="100" value="${esc(c.enrollment||0)}"></label><button class="button-small" type="submit">Enregistrer la classe</button></form></section>`;}
function subjectForm(sub={}){return `<section class="drawer-section"><h3>${sub.code?'Modifier la matière':'Créer une matière'}</h3><form id="subject-form" data-record-id="${esc(sub.code||'')}"><label>Code<input name="code" required maxlength="20" ${sub.code?'readonly':''} value="${esc(sub.code||'')}"></label><label>Nom<input name="name" required maxlength="100" value="${esc(sub.name||'')}"></label><label>Heures par classe<input name="weekly_hours" type="number" min="0" max="40" value="${esc(sub.weekly_hours||0)}"></label><label>Couleur<input name="color" type="color" value="${/^#[\da-f]{6}$/i.test(sub.color||'')?sub.color:'#5274dd'}"></label><label>Salle habituelle<input name="usual_room" maxlength="60" value="${esc(sub.usual_room||'')}"></label><button class="button-small" type="submit">Enregistrer la matière</button></form></section>`;}
async function openNewClass(){openDrawer(classForm());}
async function openNewSubject(){try{const d=await directionQuery('/direction/settings');openDrawer(subjectForm());}catch(e){showToast(e.message,false);}}
function studentForm(student={},classes=state.classes){return `<section class="drawer-section"><h3>${student.student_id?'Modifier la fiche':'Créer une fiche élève'}</h3><form id="student-form" data-record-id="${esc(student.student_id||'')}"><label>Nom complet<input name="full_name" required maxlength="120" value="${esc(student.full_name||'')}"></label><label>Code Massar<input name="massar_id" required maxlength="32" value="${esc(student.massar_id||'')}"></label><label>Classe<select name="class_id" required>${classes.map(c=>`<option value="${esc(c.class_id)}" ${student.class_id===c.class_id?'selected':''}>${esc(c.class_id)}</option>`).join('')}</select></label><label>Numéro dans la classe<input name="class_number" type="number" min="1" max="80" required value="${esc(student.class_number||'')}"></label><label>Date de naissance<input name="birth_date" type="date" value="${esc(student.birth_date||'')}"></label><label>Courriel scolaire<input name="school_email" type="email" maxlength="180" value="${esc(student.school_email||'')}"></label><label>Statut<select name="status"><option ${student.status==='Actif'?'selected':''}>Actif</option><option ${student.status==='Inactif'?'selected':''}>Inactif</option></select></label><button class="button-small" type="submit">Enregistrer la fiche</button><span class="form-feedback" aria-live="polite"></span></form>${student.student_id&&student.status!=='Inactif'?`<button class="button-small danger" data-archive-student="${esc(student.student_id)}">Archiver l’élève</button>`:''}</section>`;}
async function openNewStudent(){try{const d=await directionQuery('/direction/classes');openDrawer(studentForm({},d.classes));}catch(e){showToast(e.message,false);}}
function teacherForm(t={},subjects=[]){return `<section class="drawer-section"><h3>${t.teacher_id?'Modifier le profil':'Créer un profil enseignant'}</h3><form id="teacher-form" data-record-id="${esc(t.teacher_id||'')}"><label>Identifiant de connexion<input name="login_id" required maxlength="60" value="${esc(t.login_id||'')}"></label><label>Nom complet<input name="full_name" required maxlength="120" value="${esc(t.full_name||'')}"></label><label>Matière<select name="subject_code" required>${subjects.map(x=>`<option value="${esc(x.code)}" ${t.subject_code===x.code?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Équipe<select name="shift"><option ${t.shift==='Matin'?'selected':''}>Matin</option><option ${t.shift==='Après-midi'?'selected':''}>Après-midi</option><option ${t.shift==='Mixte'?'selected':''}>Mixte</option></select></label><label>Courriel<input name="email" type="email" value="${esc(t.email||'')}"></label><label>Téléphone<input name="phone" value="${esc(t.phone||'')}"></label><label>Maximum d’heures par jour<input name="max_hours_day" type="number" min="1" max="12" value="${esc(t.max_hours_day||8)}"></label><label>Statut<select name="status"><option ${t.status==='Actif'?'selected':''}>Actif</option><option ${t.status==='Inactif'?'selected':''}>Inactif</option></select></label><button class="button-small" type="submit">Enregistrer le profil</button></form></section>`;}
function assignmentForm(t,a={},classes=[]){return `<section class="drawer-section"><h3>Attribution pédagogique</h3><form id="assignment-form" data-teacher-id="${esc(t.teacher_id)}"><label>Matière<select name="subject_code" required>${(state.subjectRows||[]).map(x=>`<option value="${esc(x.code)}" ${t.subject_code===x.code?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Équipe<select name="shift"><option ${t.shift==='Matin'?'selected':''}>Matin</option><option ${t.shift==='Après-midi'?'selected':''}>Après-midi</option><option ${t.shift==='Mixte'?'selected':''}>Mixte</option></select></label><label>Classes assignées<input name="classes" value="${esc(a.assigned_classes||classes.map(x=>x.class_id).join(','))}" placeholder="A1,B1"></label><label>Heures par semaine<input name="weekly_hours" type="number" min="0" max="40" value="${esc(a.weekly_hours||t.weekly_hours||0)}"></label><label>Maximum par jour<input name="max_hours_day" type="number" min="1" max="12" value="${esc(a.max_hours_day||t.max_hours_day||8)}"></label><button class="button-small" type="submit">Enregistrer les attributions</button></form></section>`;}
async function openNewTeacher(){try{const d=await directionQuery('/direction/settings');state.subjectRows=d.subjects;openDrawer(teacherForm({},d.subjects));}catch(e){showToast(e.message,false);}}
async function openStudent(id){openDrawer(`<div class="loading-state">Chargement du profil…</div>`);try{const d=await directionQuery(`/direction/students/${encodeURIComponent(id)}`),s=d.student;drawerContent.innerHTML=`<div class="drawer-heading"><h2>${esc(s.full_name)}</h2><p>Profil élève · ${esc(s.student_id)}</p></div><div class="drawer-section"><div class="detail-grid">${field('Code Massar',s.massar_id)}${field('Classe',s.class_id)}${field('Numéro',s.class_number)}${field('Date de naissance',dateLabel(s.birth_date))}${field('Statut',s.status)}${field('Courriel scolaire',s.school_email||'—')}</div></div><div class="drawer-section"><h3>Parent lié</h3>${d.parent?`<div class="detail-grid">${field('Nom',d.parent.full_name)}${field('Téléphone',d.parent.phone||'—')}${field('Courriel',d.parent.email||'—')}${field('Compte',statusLabel(d.parent.account_status))}</div>`:`<p class="drawer-subtitle">Aucune fiche parent liée.</p>`}</div><div class="drawer-section"><h3>Emploi du temps · ${d.timetable.length} cours hebdomadaires</h3>${miniTimetable(d.timetable)}</div><div class="drawer-section"><h3>Historique des présences · ${d.attendance.length} lignes</h3>${d.attendance.length?`<div class="drawer-scroll"><table class="drawer-table"><tbody>${d.attendance.map(a=>`<tr><td>${dateLabel(a.lesson_date)}<br><span class="drawer-subtitle">${esc(a.day)} · ${esc(a.slot_code)} · ${esc(a.subject_name)}</span></td><td>${badge(a.status)}${a.corrected_status?`<br><span class="drawer-subtitle">Corrigé : ${esc(statusLabel(a.corrected_status))}</span>`:''}</td></tr>`).join('')}</tbody></table></div>`:`<p class="drawer-subtitle">Aucun historique de présence.</p>`}</div>${d.explanations.length?`<div class="drawer-section"><h3>Justifications</h3>${d.explanations.map(e=>`<p class="drawer-subtitle">${dateLabel(e.absence_date)} · ${badge(e.status)} · ${esc(e.reason)}${e.decided_by?` · ${esc(e.decided_by)} · ${dateLabel(e.decided_at,{dateStyle:'medium',timeStyle:'short'})}`:''}</p>`).join('')}</div>`:''}${d.entryDecisions.length?`<div class="drawer-section"><h3>Décisions d’accès</h3>${d.entryDecisions.map(e=>`<p class="drawer-subtitle">${badge(e.status)} · ${esc(e.reason||'')} · ${dateLabel(e.decided_at)}${e.authorized_lesson_id?` · ${esc(e.authorized_lesson_id)} le ${dateLabel(e.authorized_lesson_date)}`:''}</p>`).join('')}</div>`:''}${d.correctionHistory?.length?`<div class="drawer-section"><h3>Historique des corrections</h3>${d.correctionHistory.map(c=>`<p class="drawer-subtitle">${dateLabel(c.lesson_date)} · ${statusLabel(c.original_status)} → ${statusLabel(c.corrected_status)} · ${esc(c.reason)} · ${esc(c.actor)} · ${dateLabel(c.corrected_at,{dateStyle:'medium',timeStyle:'short'})}</p>`).join('')}</div>`:''}${d.explanationHistory?.length?`<div class="drawer-section"><h3>Historique des décisions de justification</h3>${d.explanationHistory.map(h=>`<p class="drawer-subtitle">${badge(h.action)} · ${esc(h.reason||'')} · ${esc(h.decided_by||'')} · ${dateLabel(h.decided_at,{dateStyle:'medium',timeStyle:'short'})}</p>`).join('')}</div>`:''}${d.entryHistory?.length?`<div class="drawer-section"><h3>Historique des décisions de retour</h3>${d.entryHistory.map(h=>`<p class="drawer-subtitle">${badge(h.action)} · ${esc(h.reason||'')} · ${esc(h.actor_user_id||'')} · ${dateLabel(h.created_at,{dateStyle:'medium',timeStyle:'short'})}${h.authorized_lesson_id?` · ${esc(h.authorized_lesson_id)} le ${dateLabel(h.authorized_lesson_date)}`:''}</p>`).join('')}</div>`:''}`;drawerContent.insertAdjacentHTML('beforeend',studentForm(s));}catch(error){drawerContent.innerHTML=`<div class="inline-error">${esc(error.message)}</div>`;}}
async function openTeacher(id){openDrawer(`<div class="loading-state">Chargement du profil…</div>`);try{const d=await directionQuery(`/direction/teachers/${encodeURIComponent(id)}`),t=d.teacher;drawerContent.innerHTML=`<div class="drawer-heading"><h2>${esc(t.full_name)}</h2><p>${esc(t.teacher_id)} · ${esc(t.subject_name)}</p></div><div class="drawer-section"><div class="detail-grid">${field('Matière',t.subject_name)}${field('Équipe',t.shift)}${field('Courriel',t.email)}${field('Téléphone',t.phone)}${field('Heures par semaine',t.weekly_hours)}${field('Maximum par jour',t.max_hours_day)}</div></div><div class="drawer-section"><h3>Classes assignées</h3><p class="drawer-subtitle">${d.classes.map(c=>esc(c.class_id)).join(' · ')||'Aucune classe'}</p></div><div class="drawer-section"><h3>Emploi du temps · ${d.timetable.length} cours</h3>${miniTimetable(d.timetable)}</div><div class="drawer-section"><h3>Horaires de travail</h3><div class="drawer-scroll"><table class="drawer-table"><tbody>${d.schedule.map(x=>`<tr><td>${esc(x.day)}</td><td>${esc(x.shift)}</td><td>${esc(x.shift_start)}–${esc(x.shift_end)}</td><td>${esc(x.lesson_hours)} h</td><td>${esc(x.day_status)}</td></tr>`).join('')}</tbody></table></div></div><div class="drawer-section"><h3>Absences de l’enseignant</h3>${d.absences.length?d.absences.map(a=>`<p class="drawer-subtitle">${dateLabel(a.absence_date)} · ${esc(a.type)} · ${esc(a.reason||'')}</p>`).join(''):'<p class="drawer-subtitle">Aucune absence enregistrée.</p>'}</div>`;state.subjectRows=d.subjects;drawerContent.insertAdjacentHTML('beforeend',teacherForm(t,d.subjects)+assignmentForm(t,d.assignment,d.classes));}catch(error){drawerContent.innerHTML=`<div class="inline-error">${esc(error.message)}</div>`;}}
async function openClass(id,tab='students'){openDrawer(`<div class="loading-state">Chargement de la classe…</div>`);try{const d=await directionQuery(`/direction/classes/${encodeURIComponent(id)}`),c=d.classInfo;let body='';if(tab==='students')body=`<div class="drawer-scroll"><table class="drawer-table"><tbody>${d.students.map(s=>`<tr><td><strong>${esc(s.class_number)}.</strong> <button class="table-link" data-detail="student" data-id="${esc(s.student_id)}">${esc(s.full_name)}</button><br><span class="drawer-subtitle">${esc(s.massar_id)} · Parent : ${esc(s.parent_name||'—')}</span></td><td>${esc(s.parent_phone||'')}</td></tr>`).join('')}</tbody></table></div>`;if(tab==='schedule')body=miniTimetable(d.timetable);if(tab==='subjects')body=`<div class="drawer-scroll"><table class="drawer-table"><tbody>${d.subjectHours.map(x=>`<tr><td>${esc(x.subject_name)}</td><td>${esc(x.hours)} h</td></tr>`).join('')}</tbody></table></div>`;drawerContent.innerHTML=`<div class="drawer-heading"><h2>${esc(c.class_id)}</h2><p>${esc(c.level)} · ${esc(c.track)} · ${d.students.length} élèves</p></div><div class="section-tabs"><button class="drawer-tab ${tab==='students'?'active':''}" data-class-tab="students" data-id="${esc(id)}">Élèves</button><button class="drawer-tab ${tab==='schedule'?'active':''}" data-class-tab="schedule" data-id="${esc(id)}">Emploi du temps</button><button class="drawer-tab ${tab==='subjects'?'active':''}" data-class-tab="subjects" data-id="${esc(id)}">Matières</button></div><div class="drawer-section">${body}</div>${classForm(c)}`;}catch(error){drawerContent.innerHTML=`<div class="inline-error">${esc(error.message)}</div>`;}}
function field(label,value){return`<div class="detail-field"><span>${esc(label)}</span><strong>${esc(value||'—')}</strong></div>`;}
function miniTimetable(lessons){if(!lessons.length)return'<p class="drawer-subtitle">Aucun cours enregistré.</p>';return`<div class="drawer-scroll"><table class="drawer-table"><tbody>${lessons.map(l=>`<tr><td>${esc(l.day)} · ${esc(l.slot_code)}<br><span class="drawer-subtitle">${esc(l.start_time)}–${esc(l.end_time)}</span></td><td>${esc(l.subject_name)}<br><span class="drawer-subtitle">${esc(l.class_id||l.teacher_name)} · ${esc(l.room)}</span></td></tr>`).join('')}</tbody></table></div>`;}
function openDrawer(html){drawerContent.innerHTML=html;document.querySelector('#admin-app').classList.add('drawer-open');drawer.setAttribute('aria-hidden','false');document.querySelector('#drawer-close').focus();}
function closeDrawer(){document.querySelector('#admin-app').classList.remove('drawer-open');drawer.setAttribute('aria-hidden','true');drawerContent.innerHTML='';}
document.querySelector('#drawer-close').addEventListener('click',closeDrawer);drawerBackdrop.addEventListener('click',closeDrawer);document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeDrawer();document.querySelector('#admin-app').classList.remove('menu-open');}});

function openDecision(requestId,decision,child){if(decision==='approve'){decideRequest(requestId,'APPROUVEE');return;}openRequiredReason('Refuser la demande',`Demande liée à ${child||'cet élève'}. Le motif sera conservé dans l’historique.`,{type:'request',id:requestId});}
function openRequiredReason(title,description,target){state.dialogRequest=target;document.querySelector('#decision-title').textContent=title;document.querySelector('#decision-child').textContent=description;document.querySelector('#rejection-reason').value='';document.querySelector('#decision-form .dialog-actions').hidden=false;dialog.showModal();}
document.querySelector('#confirm-reject').addEventListener('click',async()=>{const reason=document.querySelector('#rejection-reason').value.trim();if(reason.length<3){document.querySelector('#rejection-reason').focus();showToast('Saisissez un motif d’au moins 3 caractères.',false);return;}if(state.dialogRequest?.type==='explanation')await decideExplanation(state.dialogRequest.id,'REFUSEE',reason);else if(state.dialogRequest?.type==='request')await decideRequest(state.dialogRequest.id,'REFUSEE',reason);});
async function decideRequest(requestId,decision,reason=''){try{const result=await directionQuery(`/direction/parent-requests/${encodeURIComponent(requestId)}/decision`,{method:'POST',body:JSON.stringify({decision,reason})});if(dialog.open)dialog.close();showToast(decision==='APPROUVEE'?`Compte parent activé. Identifiant : ${result.login_id||'communiqué par la Direction'}`:'La demande a été refusée et le motif conservé.');if(state.view==='requests')loadRequestRows();else renderDashboard();}catch(error){showToast(error.message,false);}}

document.querySelector('#admin-nav').addEventListener('click',event=>{const button=event.target.closest('[data-view]');if(button){loadView(button.dataset.view);}});
document.querySelector('#admin-content').addEventListener('click',event=>{
  const openView=event.target.closest('[data-open-view]');if(openView){loadView(openView.dataset.openView);return;}
  if(event.target.closest('[data-new-student]')){openNewStudent();return;}if(event.target.closest('[data-new-teacher]')){openNewTeacher();return;}
  if(event.target.closest('[data-new-class]')){openNewClass();return;}if(event.target.closest('[data-new-subject]')){openNewSubject();return;}const subjectEdit=event.target.closest('[data-edit-subject]');if(subjectEdit){directionQuery('/direction/settings').then(d=>openDrawer(subjectForm(d.subjects.find(x=>x.code===subjectEdit.dataset.editSubject)||{}))).catch(e=>showToast(e.message,false));return;}const archive=event.target.closest('[data-archive-student]');if(archive){if(confirm('Archiver cette fiche sans supprimer son historique ?'))directionQuery(`/direction/students/${encodeURIComponent(archive.dataset.archiveStudent)}/archive`,{method:'PATCH'}).then(()=>{closeDrawer();loadStudentRows();showToast('Élève archivé.');}).catch(e=>showToast(e.message,false));return;}
  const timetableEdit=event.target.closest('[data-edit-timetable]');if(timetableEdit){editTimetableLesson(timetableEdit.dataset.editTimetable);return;}
  if(event.target.closest('[data-close-drawer]')){closeDrawer();return;}
  const retry=event.target.closest('[data-retry-view]');if(retry){loadView(state.view);return;}
  const detail=event.target.closest('[data-detail]');if(detail){if(detail.dataset.detail==='student')openStudent(detail.dataset.id);if(detail.dataset.detail==='teacher')openTeacher(detail.dataset.id);if(detail.dataset.detail==='class')openClass(detail.dataset.id);return;}
  const action=event.target.closest('[data-request-action]');if(action){openDecision(action.dataset.requestId,action.dataset.requestAction,action.dataset.child);return;}
  const explanation=event.target.closest('[data-explanation-decision]');if(explanation){if(explanation.dataset.explanationDecision==='REFUSEE')openRequiredReason('Refuser la justification','Le motif sera conservé dans l’historique de décision.',{type:'explanation',id:explanation.dataset.explanationId});else decideExplanation(explanation.dataset.explanationId,explanation.dataset.explanationDecision);return;}
  const entry=event.target.closest('[data-entry-decision]');if(entry){decideEntry(entry.dataset.entryId,entry.dataset.entryDecision);return;}
  const correction=event.target.closest('[data-correct-attendance]');if(correction){correctAttendance(correction);return;}
  if(event.target.closest('[data-close-drawer]')){closeDrawer();return;}
  const tab=event.target.closest('[data-class-tab]');if(tab){openClass(tab.dataset.id,tab.dataset.classTab);return;}
  const account=event.target.closest('[data-account-status]');if(account){account.disabled=true;directionQuery(`/direction/accounts/${encodeURIComponent(account.dataset.accountId)}/status`,{method:'PATCH',body:JSON.stringify({status:account.dataset.accountStatus})}).then(()=>{showToast('Statut du compte mis à jour.');renderAccounts();}).catch(error=>{account.disabled=false;showToast(error.message,false);});return;}
  const reset=event.target.closest('[data-reset-account]');if(reset){reset.disabled=true;window.smartSchoolSupabase.functions.invoke('direction-account-management',{body:{action:'reset_password',user_id:reset.dataset.resetAccount}}).then(({data,error})=>{if(error||!data?.temporary_password)throw error||new Error('Réinitialisation invalide.');showTemporaryCredentials(reset.dataset.resetLogin,data.temporary_password,'Mot de passe réinitialisé');showToast('Mot de passe temporaire créé. Le titulaire devra le remplacer à la connexion.');renderAccounts();}).catch(error=>{reset.disabled=false;showToast(error.message||'Réinitialisation impossible.',false);});return;}
  const read=event.target.closest('[data-notification-read]');if(read){markNotification(read.dataset.notificationRead);}
  const page=event.target.closest('[data-absence-page]');if(page&&!page.disabled){state.absenceOffset=Math.max(0,state.absenceOffset+(page.dataset.absencePage==='next'?100:-100));loadAbsenceRows();}
});
adminContent.addEventListener('keydown',event=>{const item=event.target.closest('.class-card[role="button"]');if(item&&(event.key==='Enter'||event.key===' ')){event.preventDefault();openClass(item.dataset.id);}});
async function markNotification(id){try{await directionQuery(`/direction/notifications/${encodeURIComponent(id)}/read`,{method:'PATCH'});renderNotifications();}catch(error){showToast(error.message,false);}}
async function decideExplanation(id,decision,reason=''){try{const result=await directionQuery(`/direction/absence-explanations/${encodeURIComponent(id)}/decision`,{method:'POST',body:JSON.stringify({decision,reason})});if(dialog.open)dialog.close();showToast(result.message);loadAttendanceWorkflows();loadAbsenceRows();}catch(error){showToast(error.message,false);}}
async function decideEntry(id,decision){const lesson=document.querySelector(`[data-return-lesson="${CSS.escape(id)}"]`)?.value||'',date=document.querySelector(`[data-return-date="${CSS.escape(id)}"]`)?.value||'',reason=document.querySelector(`[data-return-reason="${CSS.escape(id)}"]`)?.value.trim()||'';if(reason.length<5)return showToast('Saisissez un motif d’au moins 5 caractères.',false);if(decision==='AUTORISEE'&&(!lesson||!date))return showToast('Choisissez le cours et la date du retour.',false);try{const result=await directionQuery(`/direction/entry-decisions/${encodeURIComponent(id)}/decision`,{method:'POST',body:JSON.stringify({decision,reason,authorized_lesson_id:lesson,authorized_lesson_date:date})});showToast(result.message);loadAttendanceWorkflows();}catch(error){showToast(error.message,false);}}
function correctAttendance(button){const id=button.dataset.correctAttendance;openDrawer(`<div class="drawer-heading"><h2>Corriger une présence</h2><p>${esc(button.dataset.student)} · ${esc(button.dataset.lesson)} · ${dateLabel(button.dataset.date)} · ${esc(button.dataset.slot)}</p></div><div class="drawer-section"><p>État actuel : <strong>${esc(statusLabel(button.dataset.current))}</strong></p><form id="attendance-correction-form" data-attendance-id="${esc(id)}"><label for="correction-status">Nouvel état</label><select id="correction-status" name="status" required><option value="PRESENT">Présent</option><option value="ABSENT">Absent</option><option value="NOT_RECORDED">Non renseigné</option></select><label for="correction-reason">Motif de la correction</label><textarea id="correction-reason" name="reason" minlength="5" maxlength="500" required></textarea><div class="dialog-actions"><button class="button-small" type="submit">Confirmer la correction</button><button class="button-small" type="button" data-close-drawer>Annuler</button></div></form></div>`);}
async function editTimetableLesson(id){try{const data=await directionQuery(`/direction/timetable/${encodeURIComponent(id)}`),l=data.lesson;openDrawer(`<div class="drawer-heading"><h2>Modifier un cours</h2><p>${esc(l.class_id)} · ${esc(l.lesson_id)}</p></div><div class="drawer-section"><form id="timetable-edit-form" data-lesson-id="${esc(l.lesson_id)}"><label>Jour<select name="day" required>${['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi'].map(d=>`<option ${l.day===d?'selected':''}>${d}</option>`).join('')}</select></label><label>Horaire<select name="slot_code" required>${['M1','M2','M3','M4','S1','S2','S3','S4'].map(code=>`<option value="${code}" ${l.slot_code===code?'selected':''}>${code}</option>`).join('')}</select></label><label>Matière<select name="subject_code" required>${data.subjects.map(s=>`<option value="${esc(s.code)}" ${l.subject_code===s.code?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Enseignant<select name="teacher_id" required>${data.teachers.map(t=>`<option value="${esc(t.teacher_id)}" ${l.teacher_id===t.teacher_id?'selected':''}>${esc(t.full_name)}</option>`).join('')}</select></label><label>Salle<input name="room" maxlength="40" value="${esc(l.room||'')}"></label><div class="dialog-actions"><button class="button-small" type="submit">Enregistrer le cours</button><button class="button-small" type="button" data-close-drawer>Annuler</button></div></form></div>`);}catch(error){showToast(error.message,false);}}
drawerContent.addEventListener('submit',async event=>{const form=event.target;if(!['attendance-correction-form','timetable-edit-form','student-form','teacher-form','assignment-form','class-form','subject-form'].includes(form.id))return;event.preventDefault();try{const values=Object.fromEntries(new FormData(form).entries());if(form.id==='class-form'){const id=form.dataset.recordId,url=`/direction/classes${id?`/${encodeURIComponent(id)}`:''}`;await directionQuery(url,{method:id?'PUT':'POST',body:JSON.stringify(values)});closeDrawer();loadView('classes');showToast(id?'Classe mise à jour.':'Classe créée.');}else if(form.id==='subject-form'){const id=form.dataset.recordId,url=`/direction/subjects${id?`/${encodeURIComponent(id)}`:''}`;await directionQuery(url,{method:id?'PUT':'POST',body:JSON.stringify(values)});closeDrawer();renderSettings();showToast(id?'Matière mise à jour.':'Matière créée.');}else if(form.id==='student-form'){const id=form.dataset.recordId,url=`/direction/students${id?`/${encodeURIComponent(id)}`:''}`;await directionQuery(url,{method:id?'PUT':'POST',body:JSON.stringify(values)});closeDrawer();loadStudentRows();showToast(id?'Fiche élève mise à jour.':'Élève créé.');}else if(form.id==='teacher-form'){const id=form.dataset.recordId,url=`/direction/teachers${id?`/${encodeURIComponent(id)}`:''}`;await directionQuery(url,{method:id?'PUT':'POST',body:JSON.stringify(values)});closeDrawer();loadTeacherRows();showToast(id?'Profil enseignant mis à jour.':'Profil enseignant créé.');}else if(form.id==='assignment-form'){await directionQuery(`/direction/teachers/${encodeURIComponent(form.dataset.teacherId)}/assignment`,{method:'PUT',body:JSON.stringify(values)});closeDrawer();loadTeacherRows();showToast('Attributions enregistrées.');}else if(form.id==='attendance-correction-form'){const result=await directionQuery(`/direction/attendance/${encodeURIComponent(form.dataset.attendanceId)}/corrections`,{method:'POST',body:JSON.stringify(values)});closeDrawer();showToast(result.message);loadAbsenceRows();loadAttendanceWorkflows();}else{const result=await directionQuery(`/direction/timetable/${encodeURIComponent(form.dataset.lessonId)}`,{method:'PUT',body:JSON.stringify(values)});closeDrawer();showToast(result.message);loadTimetableRows();}}catch(error){showToast(error.message,false);}});
drawerContent.addEventListener('click',event=>{const close=event.target.closest('[data-close-drawer]');if(close){closeDrawer();return;}if(event.target.closest('[data-copy-temporary]')){const inputs=[...drawerContent.querySelectorAll('input')].map(input=>input.value);if(!navigator.clipboard?.writeText){showToast('Copie indisponible. Sélectionnez les champs manuellement.',false);return;}navigator.clipboard.writeText(inputs.join('\n')).then(()=>showToast('Informations copiées.')).catch(()=>showToast('Copie indisponible. Sélectionnez les champs manuellement.',false));return;}const detail=event.target.closest('[data-detail="student"]');if(detail)openStudent(detail.dataset.id);});
document.querySelector('#mobile-menu').addEventListener('click',()=>adminApp.classList.add('menu-open'));document.querySelector('#sidebar-close').addEventListener('click',()=>adminApp.classList.remove('menu-open'));document.querySelector('#sidebar-scrim').addEventListener('click',()=>adminApp.classList.remove('menu-open'));
document.querySelectorAll('[data-open-view]').forEach(button=>button.addEventListener('click',()=>loadView(button.dataset.openView)));
window.addEventListener('hashchange',()=>{const view=location.hash.match(/^#\/direction\/([a-z]+)$/)?.[1];if(state.user?.role==='DIRECTION'&&view&&view!==state.view)loadView(view);});

document.querySelector('#admin-logout')?.addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;try{await window.smartSchoolSupabase.auth.signOut({scope:'local'});location.replace(window.smartSchoolPath());}catch{button.disabled=false;showToast('La déconnexion n’a pas pu être confirmée.',false);}});

(async()=>{try{const {data:{session}}=await window.smartSchoolSupabase.auth.getSession();if(!session){location.replace(window.smartSchoolPath());return;}const {data:user,error}=await window.smartSchoolSupabase.from('profiles').select('id,full_name,role,status').eq('id',session.user.id).single();if(error||user.status!=='ACTIVE'||user.role!=='DIRECTION'){await window.smartSchoolSupabase.auth.signOut({scope:'local'});location.replace(window.smartSchoolPath());return;}showSession({id:user.id,role:user.role,fullName:user.full_name});}catch(error){showPageError(error);}})();
